namespace {
//! moments kernel results merged over z (generators/moments_gen.cpp).
struct Mom {
    double n = 0, sum = 0, sq = 0, mn = DBL_MAX, mx = -DBL_MAX;
};
Mom merge(const detail::PerZ<5>& p) {
    Mom m;
    for (std::size_t k = 0; k < p[0].size(); ++k) {
        m.n += p[0][k], m.sum += p[1][k], m.sq += p[2][k];
        m.mn = std::min(m.mn, p[3][k]), m.mx = std::max(m.mx, p[4][k]);
    }
    return m;
}
constexpr double kInf = std::numeric_limits<double>::infinity();
constexpr int kTrunc = 1, kAll = 2;  // moments flags: v = int(voxel); every voxel (no range)
//! body(m) computes the result from m(lo, hi, center, flags) -> Mom (one kernel pass each).
//! ref(host image): the voxlib function.
template <typename I, typename Ref, typename Body>
auto moments(const I& v, Ref&& ref, Body&& body) {
    return detail::run_reduce<op::moments, kernels::moments<voxel_t<I>>, 5>(v, ref, [&](auto pass) {
        return body([&](double lo, double hi, double c, int fl) { return merge(pass(lo, hi, c, int32_t(fl))); });
    });
}
}  // namespace

template <Image I> double varianceDbl(const I& v, int bgn, int end, bool verbose) {
    return moments(v, [&](const auto& h) { return ::varianceDbl(h, bgn, end, verbose); }, [&](auto m) {
        const Mom a = m(bgn, end, 0, kTrunc);  // voxlib: two passes, the second around the mean
        if (a.n <= 1) return 0.0;
        const double mean = a.sum / a.n;
        const Mom b = m(bgn, end, mean, kTrunc);
        if (verbose) std::cout << "stddv: " << b.sq / (a.n - 1) << ", count: " << (long long)a.n << ", mean: " << mean << "  ";
        return b.sq / (a.n - 1);
    });
}
// voxlib sums in long long; floats are truncated at every step there, so they stay on voxlib.
template <Image I> int average2p(const I& v, voxel_t<I> minV) {
    if constexpr (std::is_floating_point_v<voxel_t<I>>) {
        if constexpr (std::is_same_v<I, VoxelImageT<voxel_t<I>>>) return ::average2p(v, minV);
        else return ::average2p(v.host(), minV);
    } else {
        return moments(v, [&](const auto& h) { return ::average2p(h, minV); }, [&](auto m) {
            const Mom r = m(double(minV), kInf, 0, 0);
            return int((128 + (long long)r.sum) / (1 + (long long)r.n));
        });
    }
}
template <Image I> double stdevDbl(const I& v, int bgn, int end) { return std::sqrt(vxhl::varianceDbl(v, bgn, end)); }
template <Image I> double meanDbl(const I& v) {
    return moments(v, [&](const auto& h) { return ::meanDbl(h); }, [&](auto m) { const Mom r = m(0, 0, 0, kAll); return r.n ? r.sum / r.n : 0.0; });
}
template <Image I> double minDbl(const I& v) {
    return moments(v, [&](const auto& h) { return ::minDbl(h); }, [&](auto m) { return m(-kInf, kInf, 0, 0).mn; });
}
template <Image I> double maxDbl(const I& v) {
    return moments(v, [&](const auto& h) { return ::maxDbl(h); }, [&](auto m) { return m(-kInf, kInf, 0, 0).mx; });
}
// voxlib: #(v <= threshold) / #(v != maxT(T)); NaN counts in the total only, as in voxlib.
template <Image I> double porosityDbl(const I& v, voxel_t<I> threshold) {
    using T = voxel_t<I>;
    return moments(v, [&](const auto& h) { return ::porosityDbl(h, threshold); }, [&](auto m) {
        const double nPores = m(-kInf, double(threshold), 0, 0).n;
        const double nTotal = double(v.size3().x) * v.size3().y * v.size3().z - m(double(maxT(T)), double(maxT(T)), 0, 0).n;
        return nTotal ? nPores / nTotal : 0.0;
    });
}

// voxlib histogram(img, HistBins{shift, span, nBins}, lo, hi) without the skipFrac margins; the kernel has 256 bins.
template <Image I> vars<long long> histogram(const I& v, double shift, double span, int nBins, double lo, double hi) {
    HistBins bins;
    bins.shift = shift, bins.span = span, bins.nBins = nBins;
    auto ref = [&](const auto& h) { return ::histogram(h, bins, lo, hi); };
    if (nBins < 1 || nBins > 256) return ref([&]() -> const auto& { if constexpr (std::is_same_v<I, VoxelImageT<voxel_t<I>>>) return v; else return v.host(); }());
    return detail::run_reduce<op::histogram, kernels::histogram<voxel_t<I>>, 256>(v, ref, [&](auto pass) {
        const detail::PerZ<256> p = pass(lo, hi, shift, span, int32_t(nBins));
        vars<long long> h(nBins, 0ll);
        for (int b = 0; b < nBins; ++b)
            for (double c : p[b]) h[b] += (long long)c;
        return h;
    });
}

