namespace {
//! The host image of either image kind (a DeviceImage is synced and marked modified).
template <typename T> VoxelImageT<T>& host_of(VoxelImageT<T>& v) { return v; }
template <typename T> VoxelImageT<T>& host_of(DeviceImage<T>& v) { return v.host_mut(); }
template <typename T> const VoxelImageT<T>& cmeta_of(const VoxelImageT<T>& v) { return v; }  // header data only: no sync
template <typename T> const VoxelImageT<T>& cmeta_of(const DeviceImage<T>& v) { return v.unsynced(); }
}  // namespace

// a (op) b for a second image: code 0 && / 1 || / 2 != / 3 && ! / 4 + / 5 -
template <Image I, Image J, typename Ref>
void pair_op(I& a, const J& b, int code, Ref&& ref) {
    using T = voxel_t<I>;
    static_assert(std::is_same_v<T, voxel_t<J>>);
    if (a.size3() != b.size3()) throw std::runtime_error("Image sizes do not match");
    const detail::Aux<T> o(b);
    detail::run_stencil<op::pairOp, kernels::pairOp<T>>(a, 1, [&](auto& m) { ref(m, o.host()); }, o, int32_t(code));
}
template <Image I, Image J> void and_(I& a, const J& b) { pair_op(a, b, 0, [](auto& m, const auto& o) { ::and_(m, o); }); }
template <Image I, Image J> void or_(I& a, const J& b)  { pair_op(a, b, 1, [](auto& m, const auto& o) { ::or_(m, o); }); }
template <Image I, Image J> void xor_(I& a, const J& b) { pair_op(a, b, 2, [](auto& m, const auto& o) { ::xor_(m, o); }); }
template <Image I, Image J> void not_(I& a, const J& b) { pair_op(a, b, 3, [](auto& m, const auto& o) { ::not_(m, o); }); }
template <Image I, Image J> void addEq(I& a, const J& b) { pair_op(a, b, 4, [](auto& m, const auto& o) { ::addEq(m, o); }); }
template <Image I, Image J> void subEq(I& a, const J& b) { pair_op(a, b, 5, [](auto& m, const auto& o) { ::subEq(m, o); }); }

// operate: the operation character is a kernel argument; an unsupported one (and an empty string) runs voxlib, which throws.
template <Image I> void operateUnary(I& m, const std::string& opr) {
    using T = voxel_t<I>;
    if (opr.empty() || std::string("~!-").find(opr[0]) == std::string::npos) return ::operateUnary(host_of(m), opr);
    detail::run_stencil<op::operateUnary, kernels::operateUnary<T>>(
        m, 1, [&](auto& h) { ::operateUnary(h, opr); }, int32_t(opr[0]));
}
template <Image I, Image J> void operateImg(I& m, const std::string& opr, const J& img2, double shift) {
    using T = voxel_t<I>;
    static_assert(std::is_same_v<T, voxel_t<J>>);
    if (opr.empty() || std::string("+-*/&|%").find(opr[0]) == std::string::npos) return ::operateImg(host_of(m), opr, cmeta_of(img2), shift);
    if (m.size3() != img2.size3()) throw std::runtime_error("Image dimensions do not match for operate");
    const detail::Aux<T> o(img2);
    detail::run_stencil<op::operateImg, kernels::operateImg<T>>(
        m, 1, [&](auto& h) { ::operateImg(h, opr, o.host(), shift); }, o, int32_t(opr[0]), shift);
}
template <Image I> void operateScalar(I& m, const std::string& opr, double val) {
    using T = voxel_t<I>;
    if (opr.empty() || std::string("=+-*/&|%be").find(opr[0]) == std::string::npos) return ::operateScalar(host_of(m), opr, val);
    detail::run_stencil<op::operateScalar, kernels::operateScalar<T>>(
        m, 1, [&](auto& h) { ::operateScalar(h, opr, val); }, int32_t(opr[0]), val);
}
template <Image I> void threshold101(I& v, voxel_t<I> bgn, voxel_t<I> end) {
    detail::run_stencil<op::threshold101, kernels::threshold101<voxel_t<I>>>(v, 1, [&](auto& m) { ::threshold101(m, bgn, end); }, bgn, end);
}
template <Image I> void circleOut(I& v, int X0, int Y0, int R, char dir, voxel_t<I> outVal) {
    if (dir != 'z' && dir != 'x') return ::circleOut(host_of(v), X0, Y0, R, dir, outVal);  // voxlib's error
    detail::run_stencil<op::circleOut, kernels::circleOut<voxel_t<I>>>(
        v, 1, [&](auto& m) { ::circleOut(m, X0, Y0, R, dir, outVal); }, int32_t(X0), int32_t(Y0), int32_t(R),
        int32_t(dir == 'z' ? 0 : 1), outVal);
}
template <Image I, Image J> void mapToFrom(I& v, const J& v2, voxel_t<I> vmin, voxel_t<I> vmax, double scale, double shift) {
    using T = voxel_t<I>;
    static_assert(std::is_same_v<T, voxel_t<J>>);
    const VoxelImageT<T>& a = cmeta_of(v);
    const VoxelImageT<T>& b = cmeta_of(v2);
    int3 Dn((a.X0() - b.X0()) / a.dx() + 0.5);  // as voxlib
    const detail::Aux<T> src(v2);
    auto vref = [&](auto& m) { ::mapToFrom(m, src.host(), vmin, vmax, scale, shift); };
    if (a.size3() != b.size3() || Dn.x != 0 || Dn.y != 0 || Dn.z != 0) return vref(host_of(v));  // other grid: voxlib
    detail::run_stencil<op::mapFrom, kernels::mapFrom<T>>(v, 1, vref, src, vmin, vmax, scale, shift);
}

// paint / paint_add: the shape's parameters are kernel arguments; voxel centres are (index + 0.5)·dx + X0.
template <Image I> void paint_shape(I& v, const VoxLib::shape& sh, int mode) {
    using T = voxel_t<I>;
    auto ref = [&](auto& m) { if (mode == 0) ::VoxLib::paint(m, sh); else ::VoxLib::paintAdd(m, sh); };
    const VoxelImageT<T>& meta = cmeta_of(v);
    const dbl3 dx = meta.dx(), x0 = meta.X0();
    const int32_t iv = sh.insidev;
    if (sh.polyType == 's' || sh.polyType == 'c' || sh.polyType == 'k') {
        std::array<double, 7> p{};
        if (sh.polyType == 's') p = static_cast<const VoxLib::sphere&>(sh).params();
        if (sh.polyType == 'c') p = static_cast<const VoxLib::cylinder&>(sh).params();
        if (sh.polyType == 'k') p = static_cast<const VoxLib::kube&>(sh).params();
        const int32_t kind = sh.polyType == 's' ? 0 : sh.polyType == 'c' ? 1 : 2;
        detail::run_stencil<op::paintShape, kernels::paintShape<T>>(
            v, 1, ref, kind, int32_t(mode), iv, dx.x, dx.y, dx.z, x0.x, x0.y, x0.z, p[0], p[1], p[2], p[3], p[4], p[5], p[6]);
    } else if (sh.polyType == 't') {
        const auto p = static_cast<const VoxLib::triangular&>(sh).params();
        detail::run_stencil<op::paintTriangular, kernels::paintTriangular<T>>(
            v, 1, ref, int32_t(mode), iv, dx.x, dx.y, dx.z, x0.x, x0.y, x0.z, p[0], p[1], p[2], p[3], p[4], p[5], p[6], p[7], p[8], p[9]);
    } else {
        ref(host_of(v));  // other shapes (not exposed to Python): voxlib
    }
}
template <Image I> void paint(I& v, const VoxLib::shape& sh) { paint_shape(v, sh, 0); }
template <Image I> void paintAdd(I& v, const VoxLib::shape& sh) { paint_shape(v, sh, 1); }

template <Image I, Image J> void copyFrom(I& a, const J& b) {
    pair_op(a, b, 6, [](auto& m, const auto& o) { m.data_ = o.data_; });
}
// delense032's merge: where `other` equals `value`, the image is set to it
template <Image I, Image J> void set_where_equal(I& a, const J& other, voxel_t<I> value) {
    using T = voxel_t<I>;
    if (a.size3() != other.size3()) throw std::runtime_error("Image sizes do not match");
    const detail::Aux<T> o(other);
    detail::run_stencil<op::setWhereEqual, kernels::setWhereEqual<T>>(
        a, 1, [&](auto& m) { const auto& h = o.host(); for (std::size_t i = 0; i < m.data_.size(); ++i) if (h.data_[i] == value) m.data_[i] = value; }, o, value);
}
namespace {
//! Run f(DeviceImage&) on `v`: a VoxelImageT is copied in and moved back after f succeeded (so an exception leaves it intact).
template <typename T, typename F> void on_device(VoxelImageT<T>& v, F&& f) { DeviceImage<T> d(v); f(d); v = std::move(d.host_mut()); }
template <typename T, typename F> void on_device(DeviceImage<T>& d, F&& f) { f(d); }
}  // namespace

// voxlib VoxelImageT::fillHoles: shrink/grow chains against copies of the image; here all on DeviceImages.
template <Image I> void fillHoles(I& v, int maxHoleRadius) {
    using T = voxel_t<I>;
    if (get_backend() == Backend::Voxlib) return ::fillHoles(host_of(v), maxHoleRadius);
    on_device(v, [&](DeviceImage<T>& self) {
        DeviceImage<T> tmp{VoxelImageT<T>(self.size3(), T(0))};
        copyFrom(tmp, self);
        shrinkPore(tmp);
        for (int i = 0; i < 6; ++i) { growPore(tmp); or_(tmp, self); }
        copyFrom(self, tmp);
        growPore(tmp);
        for (int i = 0; i < 4; ++i) { shrinkPore(tmp); and_(tmp, self); }
        copyFrom(self, tmp);
        if (maxHoleRadius > 1) {
            for (int i = 0; i < maxHoleRadius; ++i) shrinkPore(tmp);
            for (int i = 0; i < maxHoleRadius * 4; ++i) { growPore(tmp); or_(tmp, self); }
            copyFrom(self, tmp);
            for (int i = 0; i < maxHoleRadius; ++i) growPore(tmp);
            for (int i = 0; i < maxHoleRadius * 3; ++i) { shrinkPore(tmp); and_(tmp, self); }
            copyFrom(self, tmp);
        }
    });
}

// voxlib _delense032 (growBox(2), a chain of median032 / FaceMedGrowToFrom, a merge, shrinkBox(2)).
// Labels outside the voxel type's range (voxlib compares and converts them differently) run voxlib.
template <Image I> bool _delense032(I& v, int nItrs, int nAdj0, int nAdj1, intOr<voxel_t<I>> lbl0, intOr<voxel_t<I>> lbl1) {
    using T = voxel_t<I>;
    auto inRange = [](auto l) { return double(l) >= double(std::numeric_limits<T>::lowest()) && double(l) <= double(std::numeric_limits<T>::max()); };
    if (get_backend() == Backend::Voxlib || !inRange(lbl0) || !inRange(lbl1))
        return ::_delense032(host_of(v), nItrs, nAdj0, nAdj1, lbl0, lbl1);
    host_of(v).growBox(2);
    on_device(v, [&](DeviceImage<T>& d) {
        DeviceImage<T> vimgo{VoxelImageT<T>(d.unsynced())};  // the grown image, copied on the host before any upload
        const T l0 = T(lbl0), l1 = T(lbl1);
        for (int i = 0; i < nItrs; ++i) median032(d, 25, nAdj1, l0, l1);
        FaceMedGrowToFrom(d, l1, l0, 1);
        FaceMedGrowToFrom(d, l0, l1, -1);
        for (int i = 0; i < 2 * nItrs; ++i) { median032(d, nAdj0, 25, l0, l1); FaceMedGrowToFrom(d, l0, l1, -1); }
        FaceMedGrowToFrom(d, l0, l1, -3);
        FaceMedGrowToFrom(d, l0, l1, -1);
        FaceMedGrowToFrom(d, l0, l1, -1);
        FaceMedGrowToFrom(vimgo, l1, l0, 2);
        FaceMedGrowToFrom(vimgo, l1, l0, 2);
        set_where_equal(d, vimgo, l1);
    });
    host_of(v).shrinkBox(2);
    return false;  // as voxlib (`return 0`)
}

